from collections import deque

def balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)                  # push the opener
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False                  # wrong or missing opener
    return not stack                          # leftovers were never closed

print(balanced("{[()]}"), balanced("([)]"))   # True False

